import { tv, type VariantProps } from "@/lib/beton/tv";

export const text = tv({
  base: "font-sans text-foreground",
  variants: {
    size: {
      sm: "text-caption",
      md: "text-body",
      lg: "text-xl leading-relaxed",
    },
    weight: {
      regular: "font-normal",
      medium: "font-medium",
      bold: "font-bold",
    },
    mono: {
      true: "font-mono",
    },
  },
  defaultVariants: {
    size: "md",
    weight: "regular",
    mono: false,
  },
});

export const heading = tv({
  base: "font-display text-foreground text-balance",
  variants: {
    size: {
      sm: "text-2xl font-extrabold leading-tight sm:text-h4",
      md: "text-3xl font-extrabold leading-none tracking-tight sm:text-4xl lg:text-h3",
      lg: "text-4xl font-black leading-none tracking-tight sm:text-5xl lg:text-h2",
      xl: "text-5xl font-black leading-[0.95] tracking-tighter sm:text-7xl lg:text-h1",
    },
    uppercase: {
      true: "uppercase",
    },
  },
  defaultVariants: {
    size: "md",
    uppercase: false,
  },
});

export type TextVariants = VariantProps<typeof text>;
export type HeadingVariants = VariantProps<typeof heading>;

import { heading, text, type HeadingVariants, type TextVariants } from "@/lib/beton/recipes/text.recipe";
import type { ComponentProps } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

export interface TextProps extends ComponentProps<"p">, TextVariants {
  render?: RenderProp;
}

export function Text({ size = "md", weight, mono, className, render, ...props }: TextProps) {
  return renderElement(
    "p",
    { ...props, "data-size": size, className: text({ size, weight, mono, class: className }) },
    render,
  );
}

type Level = 1 | 2 | 3 | 4 | 5 | 6;

const DEFAULT_SIZE: Record<Level, NonNullable<HeadingVariants["size"]>> = {
  1: "xl",
  2: "lg",
  3: "md",
  4: "sm",
  5: "sm",
  6: "sm",
};

export interface HeadingProps extends ComponentProps<"h2">, HeadingVariants {
  /** The semantic heading level. Visual size follows it unless `size` is set. */
  level?: Level;
  render?: RenderProp;
}

export function Heading({ level = 2, size, uppercase, className, render, ...props }: HeadingProps) {
  const resolvedSize = size ?? DEFAULT_SIZE[level];
  return renderElement(
    `h${level}`,
    {
      ...props,
      "data-size": resolvedSize,
      className: heading({ size: resolvedSize, uppercase, class: className }),
    },
    render,
  );
}
